 async function saveGroups(){if(!channel)return;setBusy(true);setError("");try{const allowedGroupIds=[...new Set(ids.split(/[\r\n,]+/).map(v=>v.trim()).filter(v=>v.endsWith("@g.us")))];const v=await api<Groups>("/api/backend/channels/"+channel.id+"/group-settings",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({groupsEnabled:groups.groupsEnabled,allowedGroupIds})});setGroups(v);setIds(v.allowedGroupIds.join("\n"));setNotice("Regras de grupos salvas.");}catch(e){setError(e instanceof Error?e.message:"Falha ao salvar grupos.");}finally{setBusy(false);}}
