 async function createDepartment(){const name=newName.trim();if(!name)return;const key=name.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().replace(/[^A-Z0-9_-]/g,"_").slice(0,40);setError("");try{await api("/api/backend/departments",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name,key,keywords:[]})});setDepartments(await api<Department[]>("/api/backend/departments"));setNewName("");setNotice("Departamento criado.");}catch(e){setError(e instanceof Error?e.message:"Falha ao criar departamento.");}}
