 async function loadBrandImage(kind:"logoLight"|"logoDark"|"favicon",file?:File){if(!file)return;if(!["image/png","image/jpeg","image/webp","image/svg+xml"].includes(file.type)){setError("Use PNG, JPEG, SVG ou WebP.");return;}setError("");try{if(file.type==='image/svg+xml'){const source=await file.text();if(source.length>19000||/<!DOCTYPE|<!ENTITY|<script|<foreignObject|\son\w+\s*=|(?:href|src)\s*=\s*["'](?!#)/i.test(source))throw Error('Use um SVG simples, sem scripts ou referências externas, com até 19 KB.');const data='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(source)));setBrand(v=>({...v,[kind]:data}));setNotice('SVG carregado. Salve a identidade visual.');return;}const raw=await new Promise<HTMLImageElement>((resolve,reject)=>{const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Não foi possível abrir essa imagem."))};img.src=url;});const maxW=kind==="favicon"?96:560,maxH=kind==="favicon"?96:220;const scale=Math.min(1,maxW/raw.width,maxH/raw.height);const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(raw.width*scale));canvas.height=Math.max(1,Math.round(raw.height*scale));const ctx=canvas.getContext("2d");if(!ctx)throw new Error("Seu navegador não conseguiu preparar a imagem.");ctx.drawImage(raw,0,0,canvas.width,canvas.height);let data=canvas.toDataURL("image/webp",0.78);if(data.length>23000)data=canvas.toDataURL("image/webp",0.48);if(data.length>26000)throw new Error("A imagem ainda ficou grande demais. Escolha um arquivo mais simples ou menor.");setBrand(v=>({...v,[kind]:data}));setNotice(kind==="favicon"?"Favicon carregado. Salve a identidade visual para publicar.":"Logo carregado. Salve a identidade visual para publicar.");}catch(e){setError(e instanceof Error?e.message:"Falha ao preparar a imagem.");}}
