 async function sendMailTest(){const to=mailRecipient.trim();if(!to||!to.includes("@")){setError("Informe um endereço válido para receber o teste.");return;}setMailBusy("send");setMailResult("");setError("");try{const result=await api<MailTestResult>("/api/backend/mail/test",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({to})});setMailResult(result.delivered?"Teste aceito pelo servidor. Confira a caixa de entrada e o spam.":result.reason||"O servidor não aceitou o envio.");}catch(e){setError(e instanceof Error?e.message:"Não foi possível enviar o teste.");}finally{setMailBusy(null);}}
